// ===== Linux中華機(jsgamelauncher)用の下準備 =====
// ブラウザ用のHTMLの部品(ボタン・オープニング動画・ゲームオーバー画面など)が無い環境でも止まらないよう、
// 見つからない部品の代わりに「何もしない部品」を返す
const PORT_HANDHELD = true;
(function () {
  const realGet = document.getElementById ? document.getElementById.bind(document) : () => null;
  const noop = () => {};
  const dummy = () => ({
    style: {}, dataset: {}, value: 'AAA', textContent: '', innerHTML: '',
    classList: { add: noop, remove: noop, toggle: noop, contains: () => false },
    addEventListener: noop, removeEventListener: noop, setAttribute: noop, removeAttribute: noop,
    appendChild: noop, focus: noop, blur: noop, load: noop, pause: noop,
    play: () => Promise.reject(new Error('no video')),
    getBoundingClientRect: () => ({ x: 0, y: 0, width: 0, height: 0, left: 0, top: 0 }),
  });
  document.getElementById = (id) => realGet(id) || dummy();
  if (!document.body) { try { document.body = dummy(); } catch (e) {} }
})();
