const gpPrev = { left: false, right: false, up: false, down: false, A: false, B: false, C: false };
window.addEventListener('gamepadconnected', () => {
  gpNotify = 120;
});
let gamepadBlocked = false;
let padMode = false;
function setPadMode(on) {
  if (padMode === on) return;
  padMode = on;
  if (document.body && document.body.classList) document.body.classList.toggle('padmode', on);
}
// 画面をタッチしたら、タッチボタンを出し直す
window.addEventListener('touchstart', () => setPadMode(false), { passive: true });
let gpSelectPrev = false, gpStartPrev = false;
function pollGamepadSafe() { try { pollGamepad(); } catch (e) {} }
function pollGamepad() {
  if (gamepadBlocked) return;
  let pads = [];
  try {
    pads = navigator.getGamepads ? navigator.getGamepads() : [];
  } catch (e) {
    gamepadBlocked = true; // このコンテキストではgamepad APIが権限ポリシーで禁止されている(例: Claudeのプレビューiframe)
    return;
  }
  let gp = null;
  for (const p of pads) {
    if (p) {
      gp = p;
      break;
    }
  }
  if (!gp) {
    // 2026-10-26 パッドが外れた・電池切れ・スリープの時に、押していたボタンが押しっぱなしのまま残らないようにする
    // (前は右を押したままガードしていると、外れた後もずっと右へ歩いてガードしたままになっていた)
    ['left', 'right', 'up', 'down', 'A', 'B', 'C'].forEach((k) => {
      if (gpPrev[k]) {
        keys[k] = false;
        gpPrev[k] = false;
      }
    });
    return;
  }
  unlockAudio();
  const DEAD = 0.35;
  const ax0 = gp.axes[0] || 0,
    ax1 = gp.axes[1] || 0;
  const btn = (i) => !!(gp.buttons[i] && gp.buttons[i].pressed);
  const cur = {
    left: btn(14) || ax0 < -DEAD,
    right: btn(15) || ax0 > DEAD,
    up: btn(12) || ax1 < -DEAD,
    down: btn(13) || ax1 > DEAD,
    // 中華機版:Anbernicの文字どおり、右のA=攻撃・下のB=ガード(標準配置では下=0番、右=1番)
    A: btn(1) || btn(5) || btn(7), // 右のボタン、R1、R2
    B: btn(0) || btn(4) || btn(6), // 下のボタン、L1、L2
    C: btn(2) || btn(3), // X/Square, Y/Triangle
  };
  ['left', 'right', 'up', 'down', 'A', 'B', 'C'].forEach((k) => {
    // パッドのボタンが変わった時だけ書き換える(キーボード・タッチで押している分を消さない)
    if (cur[k] !== !!gpPrev[k]) {
      keys[k] = cur[k];
      if (cur[k]) keys[k + '_edge'] = true;
    }
    gpPrev[k] = cur[k];
  });
  // 本体のボタンを触ったら、タッチボタンを隠して画面を広げる
  if (cur.left || cur.right || cur.up || cur.down || cur.A || cur.B || cur.C) setPadMode(true);
  // SELECT:ゲームボーイ風モードの切り替え / START:タイトルやゲームオーバー画面での決定(Aと同じ)
  const sel = btn(8), st = btn(9);
  if (sel && !gpSelectPrev && typeof cycleRetro === 'function') cycleRetro();
  if (st && !gpStartPrev) {
    if (typeof togglePause === 'function' && (game.paused || canPause())) togglePause();
    else keys['A_edge'] = true;
  }
  if (sel || st) setPadMode(true);
  gpSelectPrev = sel;
  gpStartPrev = st;
}
