// 先行入力:攻撃の振り終わり近くで押したAを、この長さ(F)だけ覚えておき、振り終わった瞬間に次の攻撃を出す
// (連打のタイミングが少し早くても空振り扱いにならない。ベルトスクロールの定番の手触り)
const INPUT_BUF = 10;
const COMBO_SPECS = [
  // active: 攻撃モーションの長さ(F)。hitFrom〜hitTo: attackingの残りがこの範囲の間だけ当たる
  // 新しい絵だと1ポーズが一瞬で流れて見えたため、モーションを約1.3倍に延長。
  // 当たる瞬間も「腕・脚・T25が伸び切ったポーズ」が映るタイミングに合わせた
  //  パンチ: 4ポーズ中3枚目(拳が伸びて火花) / キック: 3ポーズ中2枚目 / T25打ち: 5ポーズ中3〜4枚目
  // stop: 当たった瞬間の一時停止(F) / shake: 画面の揺れ / spark: 火花の大きさ。段が進むほど重く(手応え調整)
  // 2026-10-05 ファイナルファイトくらいのテンポに:長さ 18/16/26→13/13/21(当たる瞬間の位置は同じ割合のまま)
  // 2026-10-07 新しい攻撃の絵(コマ数が多い)に合わせて振りを遅く:長さ 13/13/21→20/20/32。振りかぶりを見せてから当てる
  // 1・2段目は押し出しを弱く(5/7→2/3)。振りが遅くなった分、敵が離れて次の段が空振りしないように
  // 2026-10-16 ファイナルファイトのテンポに:長さ 20/20/32→14/14/24(1発約0.23秒、3段で約0.9秒)。当たる瞬間の位置は同じ割合のまま
  { dmg: 10, range: 66, active: 14, gauge: 8, knock: 2, hitFrom: 8, hitTo: 4, se: 'hitS', stop: 4, shake: 3, spark: 1.0 },
  { dmg: 12, range: 70, active: 14, gauge: 8, knock: 3, hitFrom: 9, hitTo: 5, se: 'hitM', stop: 5, shake: 5, spark: 1.2 },
  { dmg: 22, range: 80, active: 24, gauge: 14, knock: 15, launch: true, hitFrom: 13, hitTo: 8, se: 'hitL', stop: 8, shake: 11, spark: 1.6 },
];

// 通常の2段(1・2段目)は正面の扇状判定、3段目(大振り/ハンマー)は全方位の円形判定で周りを巻き込む
function comboHitCheck(ex, ey) {
  const combo = player.curCombo;
  if (!combo) return false;
  const fwd = (ex - player.x) * player.facing; // 正面方向の距離(マイナスは背後)
  if (combo.launch) {
    // 3段目の大振りは前方への扇状。背後には当たらない
    const ddy = ey - player.y;
    const r = combo.range;
    return fwd > -18 && fwd * fwd + ddy * ddy < r * r;
  }
  return Math.abs(ey - player.y) < DEPTH_HIT && fwd > -14 && fwd < combo.range + 12;
}
// ---- 掴みの見た目 ----
// catchDur: 掴んだ瞬間に敵を手元へ引き寄せる時間。holdDist: 掴み中の敵との距離
// hintCount: 1プレイ中、操作ガイドを出す掴みの回数
const GRAB_SPEC = { catchDur: 8, holdDist: 38, lift: 6, throwAnim: 16, hintCount: 0 }; // 操作ガイド文字は出さない
// 投げの溜め(F)。グレーチングちゃんは投げボタンの後、引き込んで振りかぶってから放る(投げの新しい絵の2〜5コマ目)
const THROW_WIND = 16;
// 2026-10-16 ファイナルファイト風に「投げ飛ばす」:空中では横の勢いが落ちない大きな放物線で飛び、
// 地面で1回バウンドしてから滑って止まる。vx/vz:投げた瞬間の横・上の速さ / bounceVz:バウンドの高さ / bounceVx:バウンド後に残る横の勢い
const THROW_FLY = { vx: 7.5, vz: 9, bounceVz: 3.6, bounceVx: 0.55, landShake: 9, backLift: 46 };
let grabUIQueue = null;
function drawGrabUI(e, sx, y, sc, h) {
  const cx = (sx + (player.x - cameraX)) / 2 + e.facing * -2;
  const ring = y - 78 * sc;
  ctx.save();
  // 掴んでいる手元に、ロックオン風のリング
  const pulse = 1 + 0.12 * Math.sin(animTick * 0.5);
  ctx.globalAlpha = 0.85;
  ctx.strokeStyle = '#ffd23f';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(cx, ring, 15 * sc * pulse, 0, Math.PI * 2);
  ctx.stroke();
  ctx.beginPath();
  for (let i = 0; i < 4; i++) {
    const a = i * Math.PI / 2 + animTick * 0.08;
    ctx.moveTo(cx + Math.cos(a) * 19 * sc, ring + Math.sin(a) * 19 * sc);
    ctx.lineTo(cx + Math.cos(a) * 26 * sc, ring + Math.sin(a) * 26 * sc);
  }
  ctx.stroke();
  // 残り打撃数(3発目で自動的に投げる)
  const pImg = SPRITES[playerSprite()];
  const UPX = typeof UP !== 'undefined' ? UP : 1;
  const ph = (pImg && pImg.naturalHeight ? (pImg.naturalHeight * UPX) / spriteDiv(playerSprite()) : 150) * scaleAt(player.y) * charMul('player');
  const top = y - Math.max(h * UPX, ph) - 18;
  const mid = (sx + (player.x - cameraX)) / 2;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.arc(mid - 14 + i * 14, top, 5, 0, Math.PI * 2);
    ctx.fillStyle = i < player.grabHits ? '#ffd23f' : i === 2 ? 'rgba(255,110,60,0.5)' : 'rgba(0,0,0,0.55)';
    ctx.fill();
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 1.5;
    ctx.stroke();
  }
  // 操作ガイド(最初の数回だけ)
  if (game.grabHintLeft > 0) {
    const txt = 'A:殴る  後ろ+A:投げ  B:離す';
    ctx.font = 'bold 13px sans-serif';
    const tw = ctx.measureText(txt).width + 14;
    const bx = Math.max(4, Math.min(W - tw - 4, mid - tw / 2));
    ctx.globalAlpha = 0.9;
    ctx.fillStyle = 'rgba(0,0,0,0.75)';
    ctx.fillRect(bx, top - 32, tw, 20);
    ctx.fillStyle = '#ffd23f';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.fillText(txt, bx + 7, top - 22);
  }
  ctx.restore();
}

// ---- 雑魚の起き上がり・ガード ----
// guard: コンボ開始を見てからガードする確率(回避と別抽選)。hold: 構え続ける長さ
// chipMul: ガード時に通るダメージの割合。counterCd: ガードを解いた直後の反撃までの猶予
const GUARD_SPEC = { hold: 30, chipMul: 0.15, push: 3, extend: 16, counterCd: 8 };
function sprOk(k) {
  const i = k && SPRITES[k];
  return !!(i && i.complete && i.naturalWidth);
}
function enemyReactToAttack(en, allowGuard) {
  const ET = ENEMY_TYPES[en.type] || ENEMY_TYPES.A;
  const r = Math.random();
  if (r < ET.dodge) {
    en.vy = Math.random() < 0.5 ? -11.5 : 11.5; // 約8Fかけて46pxほど横へよける
    return;
  }
  if (allowGuard && ET.guard > 0 && en.atkAnim === 0 && r < ET.dodge + ET.guard) {
    en.guard = GUARD_SPEC.hold;
    en.guardShown = false;
    en.facing = player.x > en.x ? 1 : -1;
  }
}
function blockHit(e, dmg) {
  game.hudTarget = e;
  game.hudTargetT = 180;
  const chip = Math.max(1, Math.round(dmg * GUARD_SPEC.chipMul));
  e.hp = Math.max(1, e.hp - chip); // ガードで削り切られることはない
  e.vx = (e.x < player.x ? -1 : 1) * GUARD_SPEC.push;
  e.guard = Math.max(e.guard, GUARD_SPEC.extend);
  e.guardFlash = 6;
  addFx(e.x + e.facing * 22, e.y - 85 - e.z, 'gspark', null, 0.9);
  if (!e.guardShown) {
    addFx(e.x, e.y - 150, 'text', 'GUARD');
    e.guardShown = true;
  }
  hitStop = Math.max(hitStop, 2);
  shake = Math.max(shake, 2);
}
function guardBreak(e) {
  e.guard = 0;
  addFx(e.x, e.y - 150, 'text', 'BREAK!');
  addFx(e.x + e.facing * 22, e.y - 85 - e.z, 'gspark', null, 1.4);
  addScore(100, e.x, e.y - 120);
}
function startGetup(e) {
  const T = ENEMY_TYPES[e.type] || ENEMY_TYPES.A;
  e.atkAnim = 0; // 倒れる前に振りかけていた攻撃は取り消す(起きた瞬間にいきなり当たらない)
  e.atkPending = false;
  e.lunge = 0;
  e.state = 'getup';
  e.downT = 0;
  e.getup = T.getupDur || 20;
  e.getupMax = e.getup;
  e.guard = 0;
  e.thrown = false;
  addFx(e.x, e.y - 20, 'smoke', null, 1.0);
}
function drawGuardShield(e, sx, y, sc) {
  const cx = sx + e.facing * 30 * sc,
    cy = y - 72 * sc;
  const a = e.guardFlash > 0 ? 0.85 : 0.4 + 0.12 * Math.sin(animTick * 0.4);
  const s0 = e.facing > 0 ? -Math.PI / 2 : Math.PI / 2;
  ctx.save();
  ctx.beginPath();
  ctx.ellipse(cx, cy, 16 * sc, 60 * sc, 0, s0, s0 + Math.PI);
  ctx.globalAlpha = a * 0.3;
  ctx.fillStyle = '#7fe8ff';
  ctx.fill();
  ctx.globalAlpha = a;
  ctx.strokeStyle = e.guardFlash > 0 ? '#ffffff' : '#7fe8ff';
  ctx.lineWidth = 4 * sc;
  ctx.stroke();
  ctx.restore();
}
