function trackMove(o) {
  if (!o) return;
  const mv = o._px === undefined ? 0 : Math.max(Math.abs(o.x - o._px), Math.abs(o.y - o._py) * 1.5);
  o._px = o.x;
  o._py = o.y;
  if (mv > 0.2 && mv < 40) {
    o.walkDist = (o.walkDist || 0) + mv;
    o.moveT = 5;
  } else if (o.moveT > 0) o.moveT--;
}
