let chipNoise = null;
function chipPlay(parts) {
  if (!audioCtx) return;
  const now = audioCtx.currentTime;
  parts.forEach((p) => {
    const t = now + (p.at || 0), g = audioCtx.createGain();
    g.gain.setValueAtTime(p.v, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + p.d);
    g.connect(audioCtx.destination);
    if (p.w === 'noise') {
      if (!chipNoise) {
        const n = audioCtx.sampleRate;
        chipNoise = audioCtx.createBuffer(1, n, audioCtx.sampleRate);
        const ch = chipNoise.getChannelData(0);
        for (let i = 0; i < n; i++) ch[i] = Math.random() * 2 - 1;
      }
      const s = audioCtx.createBufferSource(), f = audioCtx.createBiquadFilter();
      s.buffer = chipNoise;
      f.type = p.hp ? 'highpass' : 'lowpass';
      f.frequency.value = p.hp || p.lp || 1200;
      s.connect(f); f.connect(g);
      s.start(t); s.stop(t + p.d + 0.02);
      return;
    }
    const o = audioCtx.createOscillator();
    if (p.w === 'tri') o.type = 'triangle';
    else o.setPeriodicWave(bgmWave(p.w === 'sq12' ? 0.125 : p.w === 'sq50' ? 0.5 : 0.25));
    o.frequency.setValueAtTime(p.f0, t);
    if (p.f1 && p.f1 !== p.f0) o.frequency.exponentialRampToValueAtTime(Math.max(20, p.f1), t + p.d);
    if (p.vib) {
      const l = audioCtx.createOscillator(), lg = audioCtx.createGain();
      l.frequency.value = p.vib; lg.gain.value = p.f1 * 0.02;
      l.connect(lg); lg.connect(o.frequency); l.start(t); l.stop(t + p.d + 0.02);
    }
    o.connect(g);
    o.start(t); o.stop(t + p.d + 0.02);
  });
}

// ===== GB / SFC の切り替え(BGMの音色だけ。画面の見た目は変えない) =====
// GBボタン/キーボードのGで切り替え。選んだものはこの端末に覚えておく
try { game.gbMode = localStorage.getItem('miegure_gb') === '1'; } catch (e) { game.gbMode = false; }
try { game.sfcMode = localStorage.getItem('miegure_sfc') === '1'; } catch (e) { game.sfcMode = false; }
function setSfcMode(on) {
  game.sfcMode = on; // (画面・ボタンの色は変えない。BGMだけの切り替え)
  try { localStorage.setItem('miegure_sfc', on ? '1' : '0'); } catch (e) {}
  updateRetroLabel();
}
// 画面の見た目を 通常 → ゲームボーイ風 → スーファミ風 → 通常 … の順に切り替える
// 2026-10-13:切り替えはBGMの音色だけ(スーファミ風 ⇔ ゲームボーイ風)。画面の見た目は変えない
function cycleRetro() {
  setGbMode(!game.gbMode);
  setSfcMode(false);
}
function updateRetroLabel() {
  const b = document.getElementById('btnGB');
  if (b) b.textContent = game.gbMode ? 'GB' : 'SFC'; // 今のBGMの音色
}
function setGbMode(on) {
  game.gbMode = on; // ゲームボーイ風の音色(ファミコン風の音)。画面・ボタンの色は変えない
  try { localStorage.setItem('miegure_gb', on ? '1' : '0'); } catch (e) {}
  if (on && game.sfcMode) setSfcMode(false);
  updateRetroLabel();
}
setTimeout(() => {
  if (typeof introStage !== 'undefined' && introStage !== 'done') endIntro();
  game.titleGuardUntil = 0;
}, 50);
// ===== 絵の先読み(展開) =====
// 初めて描く絵はその場で展開されるため、スマホでは一瞬カクつく(新しい技や敵が初めて出た時など。実測で1回50ms前後)。
// 使いそうな絵を2枚ずつ裏で展開しておく。一度に全部やるとiPhoneでメモリが足りなくなるので、
// ボスの絵はボスが近づいてから、イノブーの絵はイノブーで遊ぶ時だけにする
const PREWARM = { q: [], touch: [], busy: 0, max: 2, base: false, boss: false, inobu: false, bg: false };
function prewarmGroup(test) {
  Object.keys(SPRITES).forEach((k) => {
    const im = SPRITES[k];
    if (im && !im.__warm && test(k)) {
      im.__warm = 1;
      PREWARM.q.push(im);
    }
  });
}
function prewarmTick() {
  if (!PREWARM.base && game.state !== 'intro') {
    PREWARM.base = true;
    prewarmGroup((k) => !/^(kb|ib)/.test(k));
  }
  if (!PREWARM.boss) {
    const w0 = WAVES[game.waveIdx],
      w1 = WAVES[game.waveIdx + 1];
    if (boss || game.bossWarning > 0 || (w0 && w0.isBoss) || (w1 && w1.isBoss)) {
      PREWARM.boss = true;
      prewarmGroup((k) => /^kb/.test(k));
    }
  }
  if (!PREWARM.inobu && (game.hero === 'inobu' || game.heroLock)) {
    PREWARM.inobu = true;
    prewarmGroup((k) => /^ib/.test(k));
  }
  // ステージの背景(全長ぶんの1枚絵)は、初めて描く時に作って転送するので一瞬止まる(実測で約0.3秒)。
  // 他の絵の先読みが済んだら、タイトル画面の間に作って一度だけ描いておく(タイトルの絵がすぐ上から描かれるので見えない)
  if (!PREWARM.bg && PREWARM.base && game.state === 'title' && !PREWARM.q.length && !PREWARM.busy) {
    const bg = SPRITES.bgStage1;
    if (bg && bg.complete && bg.naturalWidth) {
      PREWARM.bg = true;
      const pano = getBgPanorama(bg),
        road = getRoadExt(pano);
      ctx.save();
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.drawImage(pano, 0, 0, 2, 2, 0, 0, 2, 2);
      if (road) ctx.drawImage(road, 0, 0, 2, 2, 0, 0, 2, 2);
      ctx.restore();
    }
  }
  while (PREWARM.busy < PREWARM.max && PREWARM.q.length) {
    const im = PREWARM.q.shift();
    if (!im.decode) continue;
    PREWARM.busy++;
    const done = () => PREWARM.busy--;
    im.decode().then(() => {
      done();
      PREWARM.touch.push(im);
    }, done);
  }
  // 展開できた絵は、画面の隅に1点だけ一度描いておく(初めて描く時の転送待ちも先に済ませる)。
  // この後すぐ画面全体が描き直されるので見えない
  if (PREWARM.touch.length) {
    ctx.save();
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    for (let i = 0; i < 4 && PREWARM.touch.length; i++) {
      const im = PREWARM.touch.shift();
      if (im.naturalWidth) ctx.drawImage(im, 0, 0, 1, 1);
    }
    ctx.restore();
  }
}
function loop(timestamp) {
  introSafety();
  try { prewarmTick(); } catch (e) {}
  if (typeof timestamp !== 'number') timestamp = performance.now();
  if (loopLastTime === null) loopLastTime = timestamp;
  let delta = timestamp - loopLastTime;
  loopLastTime = timestamp;
  if (delta > 250) delta = 250; // 大きすぎる間隔(タブ切り替え等)は丸めて一気に進めない
  // 60Hz/120Hzの画面で間隔がわずかにぶれても、毎フレーム同じだけ進むようにそろえる
  // (ぶれのせいで「更新0回のフレーム」と「2回のフレーム」が混ざると、動きがガクッとつっかえて見える)
  if (Math.abs(delta - FIXED_DT) < 2) delta = FIXED_DT;
  else if (Math.abs(delta - FIXED_DT / 2) < 1) delta = FIXED_DT / 2;
  loopAccumulator += delta;
  let steps = 0;
  while (loopAccumulator >= FIXED_DT && steps < MAX_CATCHUP_STEPS) {
    update();
    loopAccumulator -= FIXED_DT;
    steps++;
  }
  // 2026-10-26 遅い端末で追いつけなかった分は捨てる(ためたままだと、重い場面が終わった後に早送りのように動いていた)
  if (loopAccumulator > FIXED_DT * 2) loopAccumulator = FIXED_DT;
  if (steps > 0) {
    draw();
  }
  try { bgmTick(); } catch (e) {}
  if (game.portMsg) drawPortMsg();
  requestAnimationFrame(loop);
}
function drawPortMsg() {
  const m = game.portMsg;
  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.fillStyle = 'rgba(0,0,0,0.72)';
  ctx.fillRect(0, 0, W, H);
  ctx.textAlign = 'center';
  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 40px sans-serif';
  ctx.fillText(m.t, W / 2, H / 2 - 50);
  ctx.font = '18px sans-serif';
  ctx.fillStyle = '#cccccc';
  String(m.s || '').split('\n').slice(0, 3).forEach((line, i) => ctx.fillText(line, W / 2, H / 2 - 10 + i * 24));
  ctx.font = 'bold 26px sans-serif';
  ctx.fillStyle = '#f5b800';
  ctx.fillText('SCORE ' + String(m.score).padStart(8, '0'), W / 2, H / 2 + 70);
  if (Math.floor(performance.now() / 500) % 2 === 0) {
    ctx.font = 'bold 20px sans-serif';
    ctx.fillStyle = '#ffffff';
    ctx.fillText('A ボタンで もう一度　／　B ボタンで タイトルへ', W / 2, H / 2 + 120);
  }
  ctx.restore();
}
// 結果画面(GAME OVER など)を出してから、この時間(ms)はボタンを受け付けない。
// 倒れている間にAを連打していると、出た瞬間にその連打で「もう一度あそぶ」が押され、ステージの最初に戻っていた
const OVERLAY_GUARD_MS = 1200;
function overlayGuarded() {
  return performance.now() - (game.overlayAt || 0) < OVERLAY_GUARD_MS;
}
function showOverlay(t, s) {
  if (!game.entryDone && qualifies(game.score)) {
    startEntry(t, s); // ランキング入り:まず昔のアーケード風の名前入れ
    return;
  }
  game.overlayAt = performance.now();
  keys['A_edge'] = false;
  game.portMsg = { t: t, s: s, score: game.score };
  document.getElementById('msgTitle').textContent = t;
  document.getElementById('msgSub').textContent = s;
  document.getElementById('scoreLine').textContent = 'SCORE ' + String(game.score).padStart(8, '0');
  document.getElementById('nameEntry').style.display = 'none'; // 名前はキャンバスの名前入れ画面で入れる
  renderRanking(game.lastEntry ? game.lastEntry.name : null, game.lastEntry ? game.lastEntry.score : null);
  const noRank = !!game.atk3 || (!!game.stage2 && !game.story); // ステージ2だけ遊んだ時はランキングに載せない(通しは載せる)
  document.getElementById('rankTable').style.display = noRank ? 'none' : '';
  document.getElementById('rankNote').style.display = noRank ? 'none' : '';
  const ovEl = document.getElementById('msgOverlay');
  ovEl.className = game.state === 'clear' ? 'res-clear' : 'res-over';
  void ovEl.offsetWidth; // 出るたびに動きをやり直す
  ovEl.classList.add('pop');
  ovEl.style.display = 'flex';
}
function restart() {
  if ((game.state === 'over' || game.state === 'clear') && overlayGuarded()) return; // 出た直後の押し間違いは無視
  document.getElementById('msgOverlay').style.display = 'none';
  if (game.state === 'ranking') {
    game.state = 'title';
    return;
  }
  if (game.atk3) {
    startAttack3(); // 3分タイムアタックをもう一度
    return;
  }
  if (game.stage2 && !game.story) {
    startStage2(); // ステージ2だけをもう一度
    return;
  }
  fullRestart(); // 通しはステージ1から
  game.story = true;
  game.state = 'play';
}

const KEYMAP = {
  ArrowLeft: 'left',
  ArrowRight: 'right',
  ArrowUp: 'up',
  ArrowDown: 'down',
  z: 'A',
  x: 'B',
  c: 'C',
  Z: 'A',
  X: 'B',
  C: 'C',
};
window.addEventListener('keydown', (e) => {
  unlockAudio();
  if (e.target && e.target.tagName === 'INPUT') {
    if (e.key === 'Enter' && e.target.id === 'nameInput') submitScore(); // 名前はEnterでも登録
    return; // 文字を打っている間はゲームの操作にしない
  }
  const k = KEYMAP[e.key];
  if (!k) return;
  e.preventDefault();
  if (!keys[k]) keys[k + '_edge'] = true;
  keys[k] = true;
});
window.addEventListener('keyup', (e) => {
  const k = KEYMAP[e.key];
  if (k) {
    e.preventDefault();
    keys[k] = false;
  }
});
function bind(id, k) {
  const el = document.getElementById(id);
  const on = (ev) => {
    ev.preventDefault();
    unlockAudio();
    if (!keys[k]) keys[k + '_edge'] = true;
    keys[k] = true;
  };
  const off = (ev) => {
    ev.preventDefault();
    keys[k] = false;
  };
  el.addEventListener('touchstart', on, { passive: false });
  el.addEventListener('touchend', off, { passive: false });
  // 長押しでOSのメニューが出る・通知が来る等でタッチが中断された時も離した扱いにする(ガード押しっぱなしで固まるのを防ぐ)
  el.addEventListener('touchcancel', off, { passive: false });
  el.addEventListener('contextmenu', (ev) => ev.preventDefault());
  el.addEventListener('mousedown', on);
  el.addEventListener('mouseup', off);
  el.addEventListener('mouseleave', off);
}
// ===== 十字キー(Dパッド) =====
// 十字全体で指を受け、真ん中からの向きで8方向(斜めも可)。押したまま指を滑らせると方向が変わる。
// 真ん中付近(半径12px)は「押していない」。方向が新しく入った時は押した瞬間の合図(_edge)も出すので、→→ダッシュもそのまま
(function () {
  const pad = document.querySelector ? document.querySelector('.dpad') : null; // 中華機版(HTMLの部品が無い)では何もしない
  if (!pad || !pad.getBoundingClientRect) return;
  const DIRS = ['up', 'down', 'left', 'right'];
  let touchId = null, mouseOn = false;
  const set = (want) => {
    DIRS.forEach((d) => {
      const on = !!want[d];
      if (on && !keys[d]) keys[d + '_edge'] = true;
      keys[d] = on;
      const el = document.getElementById(d);
      if (el) el.classList.toggle('on', on);
    });
  };
  const fromPoint = (x, y) => {
    const r = pad.getBoundingClientRect();
    const dx = x - (r.left + r.width / 2), dy = y - (r.top + r.height / 2);
    if (dx * dx + dy * dy < 12 * 12) return {};
    const a = (Math.atan2(dy, dx) * 180) / Math.PI; // 右=0、下=90、左=±180、上=-90
    return {
      right: a > -67.5 && a < 67.5,
      down: a > 22.5 && a < 157.5,
      left: a > 112.5 || a < -112.5,
      up: a > -157.5 && a < -22.5,
    };
  };
  const findTouch = (list) => { for (let i = 0; i < list.length; i++) if (list[i].identifier === touchId) return list[i]; return null; };
  pad.addEventListener('touchstart', (ev) => {
    ev.preventDefault();
    unlockAudio();
    if (touchId === null) {
      const t = ev.changedTouches[0];
      touchId = t.identifier;
      set(fromPoint(t.clientX, t.clientY));
    }
  }, { passive: false });
  pad.addEventListener('touchmove', (ev) => {
    ev.preventDefault();
    const t = findTouch(ev.changedTouches);
    if (t) set(fromPoint(t.clientX, t.clientY));
  }, { passive: false });
  const end = (ev) => {
    if (ev) ev.preventDefault();
    if (!ev || findTouch(ev.changedTouches)) { touchId = null; set({}); }
  };
  pad.addEventListener('touchend', end, { passive: false });
  pad.addEventListener('touchcancel', end, { passive: false });
  pad.addEventListener('contextmenu', (ev) => ev.preventDefault());
  // PCのマウスでも
  pad.addEventListener('mousedown', (ev) => { ev.preventDefault(); unlockAudio(); mouseOn = true; set(fromPoint(ev.clientX, ev.clientY)); });
  window.addEventListener('mousemove', (ev) => { if (mouseOn) set(fromPoint(ev.clientX, ev.clientY)); });
  window.addEventListener('mouseup', () => { if (mouseOn) { mouseOn = false; set({}); } });
  // アプリの切り替えなどで指が離れたことが届かなかった時も、押しっぱなしにならないように
  window.addEventListener('blur', () => { touchId = null; mouseOn = false; set({}); });
})();
(function () {
  const b = document.getElementById('btnGB');
  const tog = (ev) => { if (ev) { ev.preventDefault(); ev.stopPropagation(); } cycleRetro(); };
  b.addEventListener('touchstart', tog, { passive: false });
  b.addEventListener('mousedown', tog);
  window.addEventListener('keydown', (ev) => { if (ev.target && ev.target.tagName === 'INPUT') return; if (ev.key === 'g' || ev.key === 'G') cycleRetro(); });
  setGbMode(game.gbMode);
  setSfcMode(game.sfcMode && !game.gbMode);
})();
(function () {
  const b = document.getElementById('btnBGM');
  const label = () => { b.textContent = BGM.muted ? '♪×' : '♪'; };
  const tog = (ev) => { if (ev) { ev.preventDefault(); ev.stopPropagation(); } unlockAudio(); setBgmMuted(!BGM.muted); label(); };
  b.addEventListener('touchstart', tog, { passive: false });
  b.addEventListener('mousedown', tog);
  window.addEventListener('keydown', (ev) => { if (ev.target && ev.target.tagName === 'INPUT') return; if (ev.key === 'm' || ev.key === 'M') { setBgmMuted(!BGM.muted); label(); } });
  label();
})();
bind('btnA', 'A');
bind('btnB', 'B');
bind('btnC', 'C');
// 画面上の指が全部離れたら、押しっぱなしのボタンを全部離す(取りこぼし対策)
['touchstart', 'mousedown'].forEach((t) =>
  window.addEventListener(t, () => { try { unlockAudio(); } catch (e) {} }, { capture: true, passive: true })
);
function releaseAllKeys() {
  Object.keys(keys).forEach((k) => {
    if (!k.endsWith('_edge')) keys[k] = false; // 押した瞬間の合図(_edge)は残す(短いタップを取りこぼさない)
  });
}
['touchend', 'touchcancel'].forEach((t) =>
  window.addEventListener(t, (ev) => {
    if (ev.touches && ev.touches.length === 0) releaseAllKeys();
  })
);
window.addEventListener('blur', releaseAllKeys);
document.addEventListener('visibilitychange', () => {
  if (document.hidden) releaseAllKeys();
});


