// ===== ボス出現の演出(2026-11-10) =====
// WARNING:t は WARNING が出てからのフレーム数(0〜150)
function drawWarningFX() {
  const t = 200 - game.bossWarning;
  if (game.bossWarning <= 50) return;
  const out = Math.min(1, (game.bossWarning - 50) / 14); // 終わり際に帯が引く
  const inn = Math.min(1, t / 12); // 出だしに帯が滑り込む
  const k = Math.min(inn, out);
  const cy = H / 2;
  ctx.save();
  // 画面全体が赤く脈打つ(サイレンと同じ約0.75秒周期)+まわりを暗く
  const pulse = 0.5 + 0.5 * Math.sin((t / 45) * Math.PI * 2);
  ctx.fillStyle = `rgba(200,0,0,${(0.08 + 0.14 * pulse) * k})`;
  ctx.fillRect(0, 0, W, H);
  const vg = ctx.createRadialGradient(W / 2, H / 2, H * 0.25, W / 2, H / 2, W * 0.75);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, `rgba(40,0,0,${0.55 * k})`);
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, W, H);
  // 真ん中の黒い帯
  const PH = 64;
  ctx.globalAlpha = 0.88 * k;
  ctx.fillStyle = '#000';
  ctx.fillRect(0, cy - PH / 2, W, PH);
  ctx.globalAlpha = k;
  // 上下の警戒帯(逆向きに流れる)
  const band = (y, dir) => {
    const bh = 18, sw = 26;
    ctx.save();
    ctx.beginPath();
    ctx.rect(0, y, W, bh);
    ctx.clip();
    ctx.fillStyle = '#ffd400';
    ctx.fillRect(0, y, W, bh);
    ctx.fillStyle = '#111';
    const off = ((t * 3 * dir) % (sw * 2) + sw * 2) % (sw * 2);
    for (let x = -sw * 4 + off; x < W + sw * 2; x += sw * 2) {
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + sw, y);
      ctx.lineTo(x + sw - bh, y + bh);
      ctx.lineTo(x - bh, y + bh);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();
  };
  const slide = (1 - inn) * W;
  ctx.save();
  ctx.translate(-slide, 0);
  band(cy - PH / 2 - 22, 1);
  ctx.restore();
  ctx.save();
  ctx.translate(slide, 0);
  band(cy + PH / 2 + 4, -1);
  ctx.restore();
  // WARNING の文字:点くたびに少し大きく出て縮む。赤く光る
  const ph = game.bossWarning % 45;
  const on = ph > 8;
  if (on) {
    const pop = Math.max(0, (ph - 37) / 8); // 点いた瞬間だけ大きい
    const sz = 44 * (1 + pop * 0.25);
    ctx.font = `900 ${Math.round(sz)}px 'Arial Black', 'Hiragino Sans', sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.shadowColor = '#ff2020';
    ctx.shadowBlur = 18;
    ctx.lineWidth = 6;
    ctx.strokeStyle = '#3a0000';
    const txt = 'W A R N I N G';
    ctx.strokeText(txt, W / 2, cy - 4);
    const g = ctx.createLinearGradient(0, cy - 24, 0, cy + 18);
    g.addColorStop(0, '#ffffff');
    g.addColorStop(0.45, '#ff5a4a');
    g.addColorStop(1, '#b00000');
    ctx.fillStyle = g;
    ctx.fillText(txt, W / 2, cy - 4);
    ctx.shadowBlur = 0;
  }
  ctx.font = "bold 13px 'DotGothic16', 'Hiragino Sans', sans-serif";
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = '#ffd0c8';
  ctx.fillText('―― 強大な敵が接近中 ――', W / 2, cy + 22);
  ctx.restore();
}
// 出現中(シネマの黒帯・スポットライト)と、戦闘開始の「FIGHT!」
// 2026-11-13 出現演出の仕上げ2。nameFx=名前のロゴが押された時の集中線の長さ(F) / fill=体力ゲージが満タンまで伸びる長さ(F) / spot=スポットライトの暗さ
const BOSS_CINE = { nameFx: 46, fill: 50, spot: 0.62 };
function bossIntroActive() {
  return !!(boss && ((boss.entrance || 0) > 0 || boss.st === 'intro'));
}
function updateBossCinema() {
  const on = bossIntroActive() || (game.bossWarning > 0 && game.bossWarning < 60);
  const target = on ? 1 : 0;
  game.lbox = (game.lbox || 0) + (target - (game.lbox || 0)) * (target ? 0.12 : 0.1);
  if (game.lbox < 0.003) game.lbox = 0;
  // 出現が終わって動き出した瞬間に「FIGHT!」
  const act = bossIntroActive();
  if (game.bossIntroWas && !act && boss && !boss.dead && !(boss.dying > 0)) {
    game.fightT = 80;
    shake = Math.max(shake, 8);
    sfx('hitL');
    sfx('clang');
  }
  game.bossIntroWas = act;
  if (game.fightT > 0) game.fightT--;
  // 名前のロゴが「ドン」と押される瞬間:白い光・揺れ・集中線・振動
  const stamp = boss && (boss.kind === 'hw'
    ? boss.st === 'intro' && boss.t - HW.descend - 12 === 10
    : game.bossName === BOSS_ENTRANCE.nameDur - 18);
  if (stamp) {
    game.nameFxT = BOSS_CINE.nameFx;
    flashWhite = Math.max(flashWhite, 5);
    shake = Math.max(shake, 11);
    if (typeof vibrate === 'function') vibrate(90, true);
  }
  if (game.nameFxT > 0) game.nameFxT--;
  // ボスの体力ゲージ:出現中は空。FIGHT! から満タンまで伸びる
  if (!boss) game.bossFill = 1;
  else if (act) game.bossFill = 0;
  else if (game.bossFill < 1) {
    game.bossFill = Math.min(1, game.bossFill + 1 / BOSS_CINE.fill);
    if (Math.round(game.bossFill * BOSS_CINE.fill) % 5 === 0) sfx('cursor'); // 伸びる間「ピピピピ」
  }
}
function drawBossCinema() {
  if (game.state !== 'play') return;
  const lb = game.lbox || 0;
  if (lb > 0) {
    // スポットライト:ボスのまわり以外を少し暗く(出現中だけ)
    if (boss && bossIntroActive()) {
      const bx = boss.x - cameraX, by = boss.y - 120 * scaleAt(boss.y);
      const g = ctx.createRadialGradient(bx, by, 60, bx, by, 420);
      g.addColorStop(0, 'rgba(0,0,0,0)');
      g.addColorStop(1, `rgba(0,0,0,${BOSS_CINE.spot * lb})`);
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, W, H);
    }
    // 名前のロゴが押された瞬間の集中線(ロゴのまわりから外へ)
    const nf = game.nameFxT || 0;
    if (nf > 0 && boss) {
      const hw = boss.kind === 'hw';
      const cx = hw ? W / 2 : W * 0.3, cy = hw ? H / 2 - 58 : H - 150;
      const a = Math.min(1, nf / 14) * 0.7;
      const seed = Math.floor(nf / 2);
      ctx.save();
      ctx.translate(cx, cy);
      ctx.fillStyle = `rgba(255,255,255,${a})`;
      const N = 44;
      for (let i = 0; i < N; i++) {
        const r1 = Math.abs(Math.sin(i * 12.9898 + seed * 78.233) * 43758.5453) % 1;
        const r2 = Math.abs(Math.sin(i * 39.3467 + seed * 11.135) * 24634.6345) % 1;
        const ang = ((i + r1 * 0.8) / N) * Math.PI * 2;
        const inner = (hw ? 300 : 320) + r2 * 110 + (BOSS_CINE.nameFx - nf) * 2.2; // だんだん外へ広がる
        const wd = 0.008 + r1 * 0.014;
        ctx.beginPath();
        ctx.moveTo(Math.cos(ang) * inner, Math.sin(ang) * inner * 0.7);
        ctx.lineTo(Math.cos(ang - wd) * 1000, Math.sin(ang - wd) * 1000);
        ctx.lineTo(Math.cos(ang + wd) * 1000, Math.sin(ang + wd) * 1000);
        ctx.closePath();
        ctx.fill();
      }
      ctx.restore();
    }
    // 上下の黒帯
    const bh = Math.round(46 * lb);
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, W, bh);
    ctx.fillRect(0, H - bh, W, bh);
  }
  const ft = game.fightT || 0;
  if (ft > 0) {
    const t = 80 - ft;
    const k = Math.min(1, t / 7); // 大きく出て縮む
    const sc = 1 + (1 - k) * (1 - k) * 2.2;
    const a = ft < 16 ? ft / 16 : 1;
    ctx.save();
    ctx.globalAlpha = a;
    ctx.translate(W / 2, H / 2 - 30);
    // 横に走る光の線
    if (t < 20) {
      ctx.fillStyle = `rgba(255,255,255,${0.5 * (1 - t / 20)})`;
      ctx.fillRect(-W / 2, -3, W, 6);
    }
    ctx.scale(sc, sc);
    ctx.rotate(-0.06);
    ctx.font = "900 italic 72px 'Arial Black', 'Hiragino Sans', sans-serif";
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.lineJoin = 'round';
    ctx.lineWidth = 12;
    ctx.strokeStyle = '#000';
    ctx.strokeText('FIGHT!', 0, 0);
    const g = ctx.createLinearGradient(0, -34, 0, 30);
    g.addColorStop(0, '#fff6b0');
    g.addColorStop(0.5, '#ffb000');
    g.addColorStop(1, '#e02000');
    ctx.fillStyle = g;
    ctx.fillText('FIGHT!', 0, 0);
    if (t >= 7 && t < 13) {
      ctx.globalCompositeOperation = 'lighter';
      ctx.globalAlpha = a * (13 - t) / 6;
      ctx.fillStyle = '#fff';
      ctx.fillText('FIGHT!', 0, 0);
    }
    ctx.restore();
  }
}

// ===== 2026-11-10 全体の仕上げ:「GO」の合図/ポーズ/場面切り替えのフェード =====
function drawGoSign() {
  // 右を指す大きな矢印+「GO!」。点滅しながら右へ小さく弾む(ファイナルファイト風)
  if (game.goFlash % 24 >= 16) return;
  const t = 150 - game.goFlash;
  const bob = Math.abs(Math.sin(t * 0.26)) * 10;
  const x = W - 150 + bob, y = 122;
  ctx.save();
  ctx.translate(x, y);
  ctx.lineJoin = 'round';
  // 矢印
  ctx.beginPath();
  ctx.moveTo(-6, -15);
  ctx.lineTo(54, -15);
  ctx.lineTo(54, -32);
  ctx.lineTo(100, 0);
  ctx.lineTo(54, 32);
  ctx.lineTo(54, 15);
  ctx.lineTo(-6, 15);
  ctx.closePath();
  ctx.lineWidth = 8;
  ctx.strokeStyle = '#000';
  ctx.stroke();
  const g = ctx.createLinearGradient(0, -32, 0, 32);
  g.addColorStop(0, '#fff6b0');
  g.addColorStop(0.5, '#ffc400');
  g.addColorStop(1, '#ff6a00');
  ctx.fillStyle = g;
  ctx.fill();
  ctx.lineWidth = 2;
  ctx.strokeStyle = '#fff';
  ctx.stroke();
  // 文字
  ctx.font = "italic bold 34px 'DotGothic16', sans-serif";
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.lineWidth = 7;
  ctx.strokeStyle = '#000';
  ctx.strokeText('GO!', 30, 1);
  ctx.fillStyle = '#fff';
  ctx.fillText('GO!', 30, 1);
  ctx.restore();
}
const POLISH = { fade: 20 }; // fade=場面が切り替わった時に黒から明けるフレーム数
function canPause() {
  return game.state === 'play';
}
function setPaused(on) {
  on = !!on && canPause();
  if (!!game.paused === on) return;
  game.paused = on;
  game.pauseT = 0;
  game.pauseSel = 0;
  for (const k in keys) keys[k] = false; // 押しっぱなし・押した記録は持ちこさない
  if (audioCtx) {
    try {
      if (on) {
        sfx('cursor');
        setTimeout(() => { if (game.paused && audioCtx) { try { audioCtx.suspend(); } catch (e) {} } }, 140); // 合図の音を鳴らしてから止める
      } else {
        audioCtx.resume();
        sfx('cursor');
      }
    } catch (e) {}
  }
  const b = document.getElementById('btnPause');
  if (b) b.textContent = on ? '▶' : 'Ⅱ';
}
function togglePause() {
  if (game.paused) setPaused(false);
  else if (canPause()) setPaused(true);
}
window.addEventListener('keydown', (ev) => {
  if (ev.target && ev.target.tagName === 'INPUT') return;
  if (ev.repeat) return;
  if (ev.key === 'p' || ev.key === 'P' || ev.key === 'Escape') {
    if (game.paused || canPause()) { ev.preventDefault(); togglePause(); }
  }
});
document.addEventListener('visibilitychange', () => {
  // 別のアプリやタブに切り替えたら、遊んでいる最中は自動でポーズ
  if (document.hidden && canPause()) setPaused(true);
  else if (!document.hidden && game.paused && audioCtx) { try { audioCtx.suspend(); } catch (e) {} } // 戻ってきてもポーズ中は無音のまま
});
(function () {
  const b = document.getElementById('btnPause');
  if (!b) return;
  const tog = (ev) => { if (ev) { ev.preventDefault(); ev.stopPropagation(); } unlockAudio(); togglePause(); };
  b.addEventListener('touchstart', tog, { passive: false });
  b.addEventListener('mousedown', tog);
})();
const _plBgmTick = bgmTick;
bgmTick = function () {
  if (game.paused) return; // ポーズ中は音を止めたまま
  _plBgmTick();
};
// ポーズのメニュー(2026-11-16)。↑↓で選んでAで決定。P/STARTはいつでも「つづける」
const PAUSE_MENU = ['つづける', '最初からやり直す', '振動', 'タイトルへもどる'];
// 振動のON/OFF(この端末に覚えておく)
let vibeOn = true;
try {
  vibeOn = localStorage.getItem('miegure_vibe') !== '0';
} catch (e) {}
// タイトルへ戻る(ポーズ・結果画面から)
function goTitle() {
  const ov = document.getElementById('msgOverlay');
  if (ov) ov.style.display = 'none';
  if (game.paused) setPaused(false);
  fullRestart();
  game.diffSel = null;
  game.state = 'title';
  for (const k in keys) keys[k] = false;
}
function goTitleFromOverlay() {
  if ((game.state === 'over' || game.state === 'clear') && overlayGuarded()) return; // 出た直後の押し間違いは無視
  goTitle();
}
// 結果画面に「タイトルへ」ボタンを足す(「もう一度あそぶ」の下)
(function () {
  const ob = document.getElementById('overlayBtn');
  if (!ob || document.getElementById('titleBtn')) return;
  const b = document.createElement('button');
  b.id = 'titleBtn';
  b.textContent = 'タイトルへ';
  b.style.cssText = 'font-size:13px;padding:7px 26px;background:#16245c;color:#e2eaff;border:1px solid #7fa8ff;border-radius:3px;box-shadow:none;animation:none;';
  b.addEventListener('click', goTitleFromOverlay);
  ob.insertAdjacentElement('afterend', b);
})();
function pauseMenuInput() {
  const n = PAUSE_MENU.length;
  if (keys['up_edge']) game.pauseSel = ((game.pauseSel || 0) + n - 1) % n;
  if (keys['down_edge']) game.pauseSel = ((game.pauseSel || 0) + 1) % n;
  if (keys['A_edge'] && game.pauseT > 20) {
    const sel = game.pauseSel || 0;
    if (sel === 0) setPaused(false);
    else if (sel === 1) {
      setPaused(false);
      restart(); // 今のモードを最初から
    } else if (sel === 2) {
      vibeOn = !vibeOn;
      try {
        localStorage.setItem('miegure_vibe', vibeOn ? '1' : '0');
      } catch (e) {}
      if (vibeOn) vibrate(80, true); // ONにしたら試しに震える
    } else goTitle();
  }
}
function drawPause() {
  const t = game.pauseT || 0;
  const a = Math.min(1, t / 8);
  const JP = "'DotGothic16', 'Hiragino Sans', sans-serif";
  ctx.save();
  ctx.fillStyle = 'rgba(0,0,12,' + 0.66 * a + ')';
  ctx.fillRect(0, 0, W, H);
  // 帯
  const cy = 96;
  ctx.fillStyle = 'rgba(0,0,0,' + 0.75 * a + ')';
  ctx.fillRect(0, cy - 44, W, 88);
  ctx.fillStyle = 'rgba(245,184,0,' + a + ')';
  ctx.fillRect(0, cy - 46, W, 3);
  ctx.fillRect(0, cy + 43, W, 3);
  ctx.globalAlpha = a;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = "italic bold 64px 'DotGothic16', sans-serif";
  ctx.lineJoin = 'round';
  ctx.lineWidth = 10;
  ctx.strokeStyle = '#000';
  ctx.strokeText('PAUSE', W / 2, cy);
  const g = ctx.createLinearGradient(0, cy - 30, 0, cy + 30);
  g.addColorStop(0, '#fff6b0');
  g.addColorStop(0.55, '#ffc400');
  g.addColorStop(1, '#ff7a00');
  ctx.fillStyle = g;
  ctx.fillText('PAUSE', W / 2, cy);
  // メニュー
  const mw = 300, rh = 34, mx = W / 2 - mw / 2, my = 164;
  PAUSE_MENU.forEach((label, i) => {
    const on = i === (game.pauseSel || 0);
    const y = my + i * rh, yc = y + rh / 2 - 2;
    if (on) {
      const bg = ctx.createLinearGradient(0, y, 0, y + rh - 4);
      bg.addColorStop(0, '#3a70f0');
      bg.addColorStop(1, '#10276e');
      ctx.fillStyle = bg;
    } else ctx.fillStyle = 'rgba(10, 20, 58, 0.92)';
    ctx.fillRect(mx, y, mw, rh - 4);
    ctx.strokeStyle = on ? `rgba(255, 211, 77, ${0.65 + 0.35 * Math.sin(t / 8)})` : 'rgba(110, 145, 230, 0.5)';
    ctx.lineWidth = on ? 2 : 1;
    ctx.strokeRect(mx + 0.5, y + 0.5, mw - 1, rh - 5);
    const text = i === 2 ? '振動：' + (vibeOn ? 'ON' : 'OFF') : label;
    ctx.font = `${on ? 19 : 17}px ${JP}`;
    ctx.lineWidth = 4;
    ctx.strokeStyle = 'rgba(0,0,0,0.85)';
    ctx.strokeText(text, W / 2, yc);
    ctx.fillStyle = on ? '#ffffff' : '#9fb2e0';
    ctx.fillText(text, W / 2, yc);
    if (on) {
      const d = Math.sin(t / 6) * 2.5;
      ctx.fillStyle = '#ffe97a';
      ctx.beginPath();
      ctx.moveTo(mx - 14 + d, yc - 7);
      ctx.lineTo(mx - 4 + d, yc);
      ctx.lineTo(mx - 14 + d, yc + 7);
      ctx.fill();
    }
  });
  // 操作のおさらい
  const rows = [
    ['十字キー', 'いどう(同じ方向に2回でダッシュ)'],
    ['A', 'こうげき(つづけて押すと連続技)'],
    ['B', 'ガード(タイミングよく押すとジャスト防御)'],
    ['C', 'ジャンプ'],
    ['B を押しながら A', 'ひっさつ技(ゲージ満タンの時)'],
  ];
  const bx = W / 2 - 290, by = my + PAUSE_MENU.length * rh + 12, bw = 580, rr = 25;
  ctx.fillStyle = 'rgba(8,12,40,0.86)';
  ctx.fillRect(bx, by, bw, rows.length * rr + 18);
  ctx.strokeStyle = '#5c7cff';
  ctx.lineWidth = 2;
  ctx.strokeRect(bx + 1, by + 1, bw - 2, rows.length * rr + 16);
  ctx.font = `15px ${JP}`;
  rows.forEach((r, i) => {
    const y = by + 22 + i * rr;
    ctx.textAlign = 'right';
    ctx.fillStyle = '#ffd23f';
    ctx.fillText(r[0], bx + 170, y);
    ctx.textAlign = 'left';
    ctx.fillStyle = '#e8eeff';
    ctx.fillText(r[1], bx + 188, y);
  });
  ctx.textAlign = 'center';
  ctx.font = `15px ${JP}`;
  ctx.lineWidth = 4;
  ctx.strokeStyle = '#000';
  // 携帯機(HTMLのボタンが無い)では START だけ案内する
  const msg = typeof PORT_HANDHELD === 'undefined' ? '↑↓で選択 / Aで決定　(P・START・Ⅱボタンでも つづける)' : '↑↓で選択 / Aで決定　(STARTでも つづける)';
  ctx.strokeText(msg, W / 2, H - 24);
  ctx.fillStyle = '#fff';
  ctx.fillText(msg, W / 2, H - 24);
  ctx.restore();
}

// ================= 3分タイムアタック(2026-11-16) =================
// secs=制限時間(秒) / camX=舞台にする場所(ステージ1の正門前) / queue=出番待ちの敵の数(切らさない)
// drumEvery=ドラム缶が出る間隔(F) / corpse=倒した敵が点滅し始めるまで(F。本編より早く片付けて次を出す) / finish=FINISH!の長さ(F)
// ranks=ランクの点(「ふつう」の時) / mul=難易度ごとにランクの点へ掛ける倍率(かんたん・ふつう・むずかしい)。自動プレイの実測(ふつう約6万・むずかしい約4万)から決めた
const ATK3 = {
  secs: 180, key: 'miegure_atk3_best_', camX: 820, queue: 6, drumEvery: 40 * 60, corpse: 45, finish: 110,
  ranks: [{ r: 'S', s: 90000 }, { r: 'A', s: 70000 }, { r: 'B', s: 50000 }, { r: 'C', s: 30000 }, { r: 'D', s: 0 }],
  mul: [0.55, 1, 1.2],
};
function atk3Best() {
  try {
    return +localStorage.getItem(ATK3.key + game.diff) || 0;
  } catch (e) {
    return 0;
  }
}
function atk3Rank(score) {
  const m = ATK3.mul[game.diff] || 1;
  return ATK3.ranks.find((k) => score >= k.s * m) || ATK3.ranks[ATK3.ranks.length - 1];
}
function startAttack3() {
  fullRestart();
  game.atk3 = true;
  game.hero = game.heroLock ? 'inobu' : 'gx';
  game.heroMsg = 0;
  game.entryDone = true; // 本編のランキングには載せない(このモードのベストだけ残す)
  WAVES.splice(0, WAVES.length, { trigger: 1e9, types: [] }); // 場面の切り替えは無し(fullRestart が元に戻す)
  cameraX = ATK3.camX;
  player.x = ATK3.camX + W / 2 - 120;
  player.y = 430;
  drums = [{ x: ATK3.camX + W * 0.72, y: 470, hp: 1 }];
  game.locked = true;
  game.atkT = ATK3.secs * 60; // 残り時間(F)
  game.atkEnd = 0; // FINISH! の残り(F)
  game.atkKills = 0;
  game.atkN = 0;
  game.atkBest = atk3Best();
  game.time = ATK3.secs;
  Object.assign(TITLE_CALL, { ep: '番外編', line1: '3分タイムアタック！', line2: '倒して倒して倒しまくれ！' });
  game.titleCall = TITLE_CALL.dur;
  game.state = 'play';
}
// 次に出す敵。後半ほど重量級(B)と素早いの(C)が増える
function atk3Pick() {
  const e = 1 - game.atkT / (ATK3.secs * 60);
  const wA = 3 - 2 * e, wB = 1 + e, wC = 1 + 1.5 * e;
  const r = Math.random() * (wA + wB + wC);
  return r < wA ? 'A' : r < wA + wB ? 'B' : 'C';
}
// 本体の update の前。FINISH! の間は本体を止める(止めたフレームなら true)
function atk3Pre() {
  if (!game.atk3 || game.state !== 'play') return false;
  if (game.atkEnd > 0) {
    game.atkEnd--;
    if (game.atkEnd === 0) atk3Finish();
    return true;
  }
  game.lives = 3; // 残機は減らない
  game.locked = true; // 1画面固定
  game.waveSideCount = [0, 0];
  while (game.waveQueue.length < ATK3.queue) game.waveQueue.push({ t: atk3Pick(), fromRight: game.atkN++ % 2 === 0 });
  // 倒した敵は本編より早く片付ける(同じ種類は片付くまで次が出ないため)
  for (const e of enemies) {
    if (e.dead && e.deadTimer > ATK3.corpse && e.deadTimer < DEAD_KEEP - DEAD_BLINK) e.deadTimer = DEAD_KEEP - DEAD_BLINK;
  }
  return false;
}
// 本体の update の後。時間を進める・KOを数える
function atk3Post() {
  if (!game.atk3 || game.state !== 'play') return;
  game.goFlash = 0;
  game.waveIdx = 0;
  game.locked = true;
  for (const e of enemies) {
    if (e.dead && !e.atkCounted) {
      e.atkCounted = true;
      game.atkKills++;
    }
  }
  if (!(game.titleCall > 0) && game.atkT > 0) {
    game.atkT--;
    if (game.atkT % ATK3.drumEvery === 0 && game.atkT > 600 && drums.length < 2)
      drums.push({ x: ATK3.camX + W * (0.25 + Math.random() * 0.5), y: DEPTH_TOP + 20 + Math.random() * (DEPTH_BOT - DEPTH_TOP - 40), hp: 1 });
    if (game.atkT <= 600 && game.atkT > 0 && game.atkT % 60 === 0) sfx('cursor'); // 残り10秒のカウント
    if (game.atkT === 0) {
      // 時間切れ:FINISH!
      game.atkEnd = ATK3.finish;
      sfx('waveclear');
      shake = Math.max(shake, 12);
      flashWhite = Math.max(flashWhite, 8);
      if (typeof vibrate === 'function') vibrate(220, true);
      for (const k in keys) keys[k] = false;
    }
  }
  game.time = game.atkT > 0 ? Math.max(1, Math.ceil(game.atkT / 60)) : 0;
  game.timeSub = 0; // 本体の時計は進めない(このモードの時計で数える)
}
function atk3Finish() {
  const best = atk3Best();
  const nb = game.score > best;
  if (nb) {
    try {
      localStorage.setItem(ATK3.key + game.diff, String(game.score));
    } catch (e) {}
  }
  const rk = atk3Rank(game.score);
  game.atkRank = rk.r;
  game.state = 'clear';
  showOverlay(
    'TIME UP!',
    '3分タイムアタック [' + DIFF().name + ']\n' +
      'KO ' + game.atkKills + '体　　最大コンボ ' + (game.bestCombo || 0) + '\n' +
      (nb ? '★ NEW RECORD ★' : 'BEST ' + String(best).padStart(8, '0')) + '   RANK  ' + rk.r
  );
}
function drawAtk3() {
  if (!game.atk3 || game.state !== 'play' || game.paused) return;
  ctx.save();
  ctx.textBaseline = 'middle';
  ctx.lineJoin = 'round';
  const tc = game.titleCall > 0;
  if (!tc) {
    // 左下:KO数 / 右下:ベスト
    ctx.font = "bold 18px 'DotGothic16', sans-serif";
    ctx.lineWidth = 5;
    ctx.strokeStyle = '#000';
    ctx.textAlign = 'left';
    ctx.strokeText('KO ' + game.atkKills, 14, H - 18);
    ctx.fillStyle = '#ffd23f';
    ctx.fillText('KO ' + game.atkKills, 14, H - 18);
    const bt = 'BEST ' + String(Math.max(game.atkBest || 0, 0)).padStart(8, '0');
    ctx.textAlign = 'right';
    ctx.strokeText(bt, W - 14, H - 18);
    ctx.fillStyle = game.score > (game.atkBest || 0) && game.atkBest > 0 ? '#7dff9a' : '#ffffff';
    ctx.fillText(bt, W - 14, H - 18);
  }
  // 残り10秒:大きい数字
  if (game.atkT > 0 && game.atkT <= 600 && !tc) {
    const n = Math.ceil(game.atkT / 60), f = (game.atkT % 60) / 60; // f:1→0
    ctx.globalAlpha = 0.35 + 0.5 * f;
    ctx.textAlign = 'center';
    ctx.font = 'italic bold ' + Math.round(120 + 60 * f) + "px 'DotGothic16', sans-serif";
    ctx.lineWidth = 10;
    ctx.strokeStyle = '#000';
    ctx.strokeText(String(n), W / 2, H / 2 - 30);
    ctx.fillStyle = '#ff4030';
    ctx.fillText(String(n), W / 2, H / 2 - 30);
    ctx.globalAlpha = 1;
  }
  // FINISH!
  if (game.atkEnd > 0) {
    const e = ATK3.finish - game.atkEnd, k = Math.min(1, e / 8);
    ctx.fillStyle = 'rgba(0,0,0,' + 0.4 * k + ')';
    ctx.fillRect(0, 0, W, H);
    ctx.translate(W / 2, H / 2 - 20);
    ctx.rotate(-0.05);
    ctx.scale(2.2 - 1.2 * k, 2.2 - 1.2 * k);
    ctx.textAlign = 'center';
    ctx.font = "italic 900 96px 'Arial Black', 'Hiragino Sans', sans-serif";
    ctx.lineWidth = 14;
    ctx.strokeStyle = '#000';
    ctx.strokeText('FINISH!', 0, 0);
    const g = ctx.createLinearGradient(0, -46, 0, 46);
    g.addColorStop(0, '#fff6b0');
    g.addColorStop(0.5, '#ffb400');
    g.addColorStop(1, '#ff3a00');
    ctx.fillStyle = g;
    ctx.fillText('FINISH!', 0, 0);
  }
  ctx.restore();
}

// ================= 1フレームの流れ(入口はここ) =================
// 本体の update() / draw() の前後に、あとから足した処理(ステージ2のタイム・HUDの動き・ボス出現の演出・ポーズ・フェード)を
// ここ1か所で順番に呼ぶ。(2026-11-13 整理:前は3段重ねの包みになっていた)
// ---- ポーズ中の1フレーム(ゲームの時間を止める)。止めたままなら true ----
function updatePauseHold() {
  if (game.paused) {
    if (!canPause()) setPaused(false);
    else {
      game.pauseT = (game.pauseT || 0) + 1;
      pollGamepad(); // STARTで戻れるように、パッドだけは見る
      if (game.pauseT > 12 && audioCtx && audioCtx.state === 'running') { try { audioCtx.suspend(); } catch (e) {} } // ボタンを触って音が戻っても止め直す
      pauseMenuInput(); // メニュー(つづける/やり直す/振動/タイトルへ)
      for (const k in keys) if (k.endsWith('_edge')) keys[k] = false;
      return true; // ゲームの時間を止める
    }
  }
  return false;
}
// ---- HUDの動きとステージ2のタイム・カメラ(本体の update の後) ----
function updateHudAndStage2(counting) {
  if (game.hudTargetT > 0) game.hudTargetT--; // 左上の相手の欄を出しておく時間
  // HUDの動き:スコアの数え上がり・くらった時の点滅・COMBOのポン
  if (game.hudScore === undefined || game.hudScore > game.score) game.hudScore = game.score;
  else if (game.hudScore < game.score) game.hudScore = Math.min(game.score, game.hudScore + Math.max(10, Math.ceil((game.score - game.hudScore) * 0.2)));
  if (game.hudPrevHp !== undefined && player.hp < game.hudPrevHp && game.state === 'play') game.hudHitT = 16;
  game.hudPrevHp = player.hp;
  if (game.hudHitT > 0) game.hudHitT--;
  if (game.killStreak > (game.hudPrevStreak || 0)) game.hudComboT = 14;
  game.hudPrevStreak = game.killStreak;
  if (game.hudComboT > 0) game.hudComboT--;
  if (counting && game.state === 'play') game.s2Frames = (game.s2Frames || 0) + 1;
  if (game.stage2 && game.state === 'play' && game.locked && (boss || game.bossWarning > 0)) {
    const t = Math.min(STAGE_LENGTH - W, Math.round(cameraX / W) * W);
    cameraX += (t - cameraX) * 0.06;
    if (Math.abs(t - cameraX) < 0.5) cameraX = t;
    player.x = Math.max(cameraX + 30, Math.min(cameraX + W - 30, player.x));
  }
}
// ---- ボス出現の演出(黒帯・スポットライト・FIGHT!) ----
function updateBossCinemaState() {
  if (game.state === 'play') updateBossCinema();
  else {
    game.lbox = 0;
    game.fightT = 0;
    game.nameFxT = 0;
    game.bossIntroWas = false;
  }
}
// ---- 場面の切り替わりのフェード ----
let prevState = null;
function updateFade() {
  // 場面が切り替わったら黒から明ける
  if (game.state !== prevState) {
    if (prevState !== null && (game.state === 'title' || game.state === 'ranking' || game.state === 'play' || game.state === 'bonus'))
      game.fadeIn = POLISH.fade;
    prevState = game.state;
  }
  if (game.fadeIn > 0) game.fadeIn--;
}
// ---- 手ごたえの演出(2026-11-13):ボス撃破のK.O.スロー/体力わずかの赤い警告/HURRY UP!/振動 ----
// ko=スローにする長さ(F。この間ゲームは1/3の速さ) / lowHp=この割合以下で画面のふちが赤く脈打つ / hurry=残りこの秒数で「HURRY UP!」
const FEEL = { ko: 54, lowHp: 0.25, hurry: 30, hurryDur: 150 };
const feel = { wasDying: false, hp: null, hurryDone: false, state: null };
function vibrate(ms, strong) {
  if (!vibeOn) return; // ポーズのメニューでOFFにできる
  // スマホ本体(Androidなど対応機種だけ)と、つないでいるゲームパッドを震わせる。使えない環境では何もしない
  try {
    if (navigator.vibrate) navigator.vibrate(ms);
  } catch (e) {}
  try {
    const gps = navigator.getGamepads ? navigator.getGamepads() : [];
    for (const gp of gps) {
      if (gp && gp.vibrationActuator && gp.vibrationActuator.playEffect)
        gp.vibrationActuator.playEffect('dual-rumble', { duration: ms, strongMagnitude: strong ? 0.9 : 0.5, weakMagnitude: strong ? 0.7 : 0.3 }).catch(() => {});
    }
  } catch (e) {}
}
// K.O.スロー中は3フレームに1回だけゲームを進める。進めないフレームなら true
function updateSlowMo() {
  if (!(game.koT > 0)) return false;
  if (game.state !== 'play') {
    game.koT = 0;
    return false;
  }
  game.koT--;
  return game.koT % 3 !== 0;
}
function updateFeel() {
  const playing = game.state === 'play';
  // ボスを倒した瞬間:K.O.スロー+白い光+強い振動
  const dying = !!(boss && boss.dying > 0);
  if (dying && !feel.wasDying && playing) {
    game.koT = FEEL.ko;
    flashWhite = Math.max(flashWhite, 8);
    vibrate(220, true);
  }
  feel.wasDying = dying;
  // くらった時:短い振動
  if (playing && feel.hp !== null && player.hp < feel.hp) vibrate(player.hp <= 0 ? 160 : 45, player.hp <= 0);
  feel.hp = player.hp;
  // 残り時間わずか:1回だけ「HURRY UP!」
  if (playing && game.time > FEEL.hurry) feel.hurryDone = false;
  if (playing && game.time <= FEEL.hurry && game.time > 0 && !feel.hurryDone && !dying && !(game.titleCall > 0)) {
    feel.hurryDone = true;
    game.hurryT = FEEL.hurryDur;
    sfx('warning');
  }
  if (game.hurryT > 0) game.hurryT = playing ? game.hurryT - 1 : 0;
  // CONTINUE? が出たら、残っている「MISS!」などの文字は消す(数字と重なって読みにくかった)
  if (game.state === 'continue' && feel.state !== 'continue') {
    for (let i = fx.length - 1; i >= 0; i--) if (fx[i].type === 'text') fx.splice(i, 1);
  }
  feel.state = game.state;
}
function drawFeel() {
  if (game.state !== 'play' || game.paused) return;
  // 体力わずか:画面のふちが赤く脈打つ
  if (player.hp > 0 && player.hp <= player.maxHp * FEEL.lowHp && !(game.titleCall > 0) && !(game.lbox > 0.05)) {
    const a = 0.24 + 0.12 * Math.sin(animTick * 0.14);
    const g = ctx.createRadialGradient(W / 2, H / 2, H * 0.42, W / 2, H / 2, H * 0.88);
    g.addColorStop(0, 'rgba(255,0,0,0)');
    g.addColorStop(1, 'rgba(255,0,0,' + a + ')');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, W, H);
  }
  // HURRY UP!
  if (game.hurryT > 0 && Math.floor(game.hurryT / 10) % 2 === 0) {
    ctx.save();
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.lineJoin = 'round';
    ctx.font = "italic bold 44px 'DotGothic16', sans-serif";
    ctx.lineWidth = 8;
    ctx.strokeStyle = '#000';
    ctx.strokeText('HURRY UP!', W / 2, 150);
    ctx.fillStyle = '#ff4030';
    ctx.fillText('HURRY UP!', W / 2, 150);
    ctx.restore();
  }
  // K.O.!
  if (game.koT > 0) {
    const e = FEEL.ko - game.koT; // 出てからのフレーム
    const k = Math.min(1, e / 8);
    const sc = 2.4 - 1.4 * k;
    ctx.save();
    ctx.globalAlpha = Math.min(1, game.koT / 10) * k;
    ctx.translate(W / 2, H / 2 - 40);
    ctx.rotate(-0.06);
    ctx.scale(sc, sc);
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.lineJoin = 'round';
    ctx.font = "italic 900 104px 'Arial Black', 'Hiragino Sans', sans-serif";
    ctx.lineWidth = 14;
    ctx.strokeStyle = '#000';
    ctx.strokeText('KO!!', 0, 0);
    const g = ctx.createLinearGradient(0, -50, 0, 50);
    g.addColorStop(0, '#fff6b0');
    g.addColorStop(0.5, '#ffb400');
    g.addColorStop(1, '#ff3a00');
    ctx.fillStyle = g;
    ctx.fillText('KO!!', 0, 0);
    ctx.restore();
  }
}
const updateCore = update, drawCore = draw;
update = function () {
  if (game.paused && updatePauseHold()) return;
  if (updateSlowMo()) return; // ボス撃破のK.O.スロー
  if (atk3Pre()) return; // 3分タイムアタック(FINISH! の間は止める)
  // 瓦礫の王:名前カードが消えるまで出現演出のまま待つ(黒帯のまま、待機のポーズ)。その後に「FIGHT!」
  if (boss && boss.entrance === 1 && game.bossName > 24 && game.state === 'play') boss.entrance = 2;
  const counting = game.stage2 && game.state === 'play' && !(game.titleCall > 0) && !(boss && boss.dying > 0);
  updateCore();
  atk3Post();
  updateHudAndStage2(counting);
  updateBossCinemaState();
  updateFade();
  updateFeel();
};
draw = function () {
  drawCore();
  if (!(game.lbox > 0.3)) drawS2Time(); // ステージ2のタイム(ボス出現の黒帯の間は隠す)
  ctx.save();
  ctx.setTransform(RS, 0, 0, RS, 0, 0);
  drawBossCinema(); // ボス出現の黒帯など
  drawFeel(); // 体力わずかの警告・HURRY UP!・K.O.
  drawAtk3(); // 3分タイムアタックのKO数・カウント・FINISH!
  ctx.restore();
  if (!(game.fadeIn > 0) && !game.paused) return;
  ctx.save();
  ctx.setTransform(RS, 0, 0, RS, 0, 0);
  if (game.fadeIn > 0) {
    ctx.fillStyle = 'rgba(0,0,0,' + Math.min(1, game.fadeIn / POLISH.fade) + ')';
    ctx.fillRect(0, 0, W, H);
  }
  if (game.paused) drawPause();
  ctx.restore();
};

loop(); // 全部の準備ができてから動かし始める
